import math
import sympy
from sympy import isprime, ZZ, QQ

# Top-level setup
# The witness is expected to be a tuple (n, m, M_gen) or a dictionary with these keys.
# This parameterizes a counterexample in the following way:
#   R = Z/nZ  (where n=0 represents the integers Z)
#   S = Z/mZ  (where m=0 represents the integers Z)
#   f: R -> S is the natural projection f(x) = x mod m
#   M is the ideal generated by M_gen in S

Z = ZZ
Q = QQ

def conditions(witness) -> list[bool]:
    try:
        if isinstance(witness, dict):
            n = witness.get('n')
            m = witness.get('m')
            M_gen = witness.get('M_gen')
        elif hasattr(witness, 'n') and hasattr(witness, 'm') and hasattr(witness, 'M_gen'):
            n = witness.n
            m = witness.m
            M_gen = witness.M_gen
        elif isinstance(witness, (tuple, list)) and len(witness) == 3:
            n, m, M_gen = witness
        else:
            return [False, False, False]
            
        n = abs(int(n))
        m = abs(int(m))
        M_gen = abs(int(M_gen))
    except Exception:
        return [False, False, False]

    # H_1: R and S are commutative rings with identity
    try:
        # n=1 or m=1 would mean the trivial ring {0}, which is conventionally 
        # excluded from "rings with identity" by requiring 1 != 0.
        h1 = (n != 1 and m != 1)
    except Exception:
        h1 = False

    # H_2: f is a surjective ring homomorphism from R to S
    try:
        if m == 0:
            h2 = (n == 0)
        else:
            h2 = (n % m == 0)
    except Exception:
        h2 = False

    # ¬Q: The preimage of M under f is NOT a maximal ideal of R
    try:
        # The preimage of the ideal M = <M_gen> under f(x) = x mod m 
        # is the ideal generated by g = gcd(M_gen, m) in Z/nZ.
        g = math.gcd(M_gen, m)
        
        # In Z/nZ (and Z), an ideal <g> is maximal if and only if g is prime.
        is_maximal = isprime(g)
        neg_q = not is_maximal
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]

CONDITION_LABELS = [
    "H_1: R and S are commutative rings with identity",
    "H_2: f is a surjective ring homomorphism from R to S",
    "¬Q: The preimage of M under f is not a maximal ideal of R"
]

N_HYP = 2
NEG_Q_INDEX = 2